pub struct Session {
    by_id: HashMap<Id, Rc<RefCell<Customer>>>,
}

impl Session {
    pub fn get(&mut self, id: Id) -> Rc<RefCell<Customer>> {
        if let Some(c) = self.by_id.get(&id) {
            return Rc::clone(c);
        }
        let c = Rc::new(RefCell::new(load(id)));
        self.by_id.insert(id, Rc::clone(&c));
        c
    }
}
